module longest_valid_prefix (input clk, input rst_n, input start, input [3:0] start_index, input [7:0] b_data0, input [7:0] b_data1, input [7:0] b_data2, input [7:0] b_data3, input [7:0] b_data4, input [7:0] b_data5, input [7:0] b_data6, input [7:0] b_data7, input [3:0] b_size, output reg [3:0] result, output reg done); parameter IDLE = 2'b00; parameter COMPUTE = 2'b01; parameter DONE = 2'b10; reg [1:0] state; reg [3:0] current_index; reg [3:0] result_reg; reg done_reg; always @(posedge clk) begin if (!rst_n) begin state <= IDLE; current_index <= 0; result_reg <= 0; done_reg <=0; end else begin if (state == IDLE) begin if (start) begin state <= COMPUTE; current_index <= start_index; result_reg <=0; done_reg <=0; end end else if (state == COMPUTE) begin if (current_index < 16) begin reg [7:0] current_a; case (current_index) 0: current_a = 8'b00000001; 1: current_a = 8'b00000010; 2: current_a = 8'b00000011; 3: current_a = 8'b00000001; 4: current_a = 8'b00000010; 5: current_a = 8'b00000001; 6: current_a = 8'b00000001; 7: current_a = 8'b00000000; 8: current_a = 8'b00000000; 9: current_a = 8'b00000000; 10: current_a = 8'b00000000; 11: current_a = 8'b00000000; 12: current_a = 8'b00000000; 13: current_a = 8'b00000000; 14: current_a = 8'b00000000; 15: current_a = 8'b00000000; default: current_a = 8'b00000000; endcase reg match; match = 0; if (b_size >0) match = match | (current_a == b_data0); if (b_size >1) match = match | (current_a == b_data1); if (b_size >2) match = match | (current_a == b_data2); if (b_size >3) match = match | (current_a == b_data3); if (b_size >4) match = match | (current_a == b_data4); if (b_size >5) match = match | (current_a == b_data5); if (b_size >6) match = match | (current_a == b_data6); if (b_size >7) match = match | (current_a == b_data7); if (match) begin result_reg <= result_reg +1; current_index <= current_index +1; end else begin state <= DONE; done_reg <=1; end end else begin state <= DONE; done_reg <=1; end end else if (state == DONE) be